
import { defineComponent, PropType } from 'vue';
import { translate } from 'CoreHome';
import { Field } from 'CorePluginsAdmin';
import {
  Option,
  DIMENSION_TYPES,
} from '../../types';

export default defineComponent({
  components: {
    Field,
  },
  props: {
    selectedType: {
      type: String,
      required: true,
    },
    selectedValue: {
      type: String,
      required: true,
    },
    valueOptions: {
      type: Array as PropType<Option[]>,
      default: () => [],
    },
    isLoadingValues: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['update:selectedType', 'update:selectedValue'],
  computed: {
    typeOptions(): Option[] {
      return Object.entries(DIMENSION_TYPES).map(([key, translationKey]) => ({
        key,
        value: translate(translationKey),
      }));
    },
  },
  methods: {
    translate,
    onTypeChange(newType: string) {
      this.$emit('update:selectedType', newType);
    },
    onValueChange(newValue: string) {
      this.$emit('update:selectedValue', newValue);
    },
  },
});
